}

/* ======================  Minimap  ====================== */
function drawMinimap(){
  const ctx = STATE.ctx;
  const map = STATE.map;
  const scale = MINIMAP_SCALE;
  const offX = MINIMAP_PADDING;
  const offY = MINIMAP_PADDING;

