    for(let x=0;x<map[y].length;x++){
      const cell = map[y][x];
      if(cell===0) continue;
      let col;
      switch(cell){
        case 1: col='#777'; break;
        case 2: col='#b33'; break;
        case 3: col='#2a2'; break;
        case 4: col='#aa0'; break; // closed door
        case 5: col='#0af'; break; // exit
        default: col='#555';
      }
      ctx.fillStyle=col;
      ctx.fillRect(offX + x*scale, offY + y*scale, scale, scale);
