    const nx = STATE.player.x + (moveX/len)*MOVE_SPEED*dt;
    const ny = STATE.player.y + (moveY/len)*MOVE_SPEED*dt;
    if(!collides(nx,ny)) { STATE.player.x=nx; STATE.player.y=ny; }
