  const r = PLAYER_RADIUS;
  const cells = [
    [Math.floor(px-r), Math.floor(py-r)],
    [Math.floor(px+r), Math.floor(py-r)],
    [Math.floor(px-r), Math.floor(py+r)],
    [Math.floor(px+r), Math.floor(py+r)]
